const assert = require('node:assert/strict');
const fs = require('node:fs');
const { IDBFactory, IDBKeyRange } = require('fake-indexeddb');
globalThis.IDBKeyRange = IDBKeyRange;
globalThis.self = { crypto: require('node:crypto').webcrypto, IDBKeyRange };
const current = require('./current.cjs');
const old = require('./old.cjs');
const report = { baseline: { tag: '2.9.2', commit: '22c192b84ebdeb14e3808f57a63da0a7d4efbca7',
  schema: old.CHAT_HISTORY_SCHEMA_VERSION, idb: old.CHAT_HISTORY_IDB_VERSION },
  current: { schema: current.CHAT_HISTORY_SCHEMA_VERSION, idb: current.CHAT_HISTORY_IDB_VERSION }, results: [] };
const conversation = { id: 'compat-conversation', title: 'Synthetic compatibility', createdAt: '2026-09-10T00:00:00Z',
  updatedAt: '2026-09-10T00:00:00Z', turnCount: 2, preview: 'Synthetic' };
const scene = { writingTask: 'caption', purpose: 'share', audience: 'friends', domain: 'travel' };
const images = [{ ref: { assetId: 'image_one', contentHash: 'a'.repeat(64) }, ordinal: 1, label: 'Synthetic photo' }];
const asset = { id: 'image_one', source: 'vault_reference', originalPath: 'photos/synthetic.jpg', originalHash: 'a'.repeat(64),
  byteLength: 3, detectedMime: 'image/jpeg', acquisition: 'original_file', state: 'available', anchorPath: 'PA Chat.md',
  anchorKind: 'logical_root', createdAt: 1, owners: [] };
async function snapshot(store) {
 return { turns: await store.getTurns(conversation.id), versions: await store.listWritingVersions(conversation.id),
  assets: await store.getImageAsset('image_one'), receipts: await store.listSaveReceipts() };
}
async function main() {
 const factory = new IDBFactory();
 const writer = new current.IndexedDbChatHistoryStore('b135-compat-real-version', factory);
 await writer.initialize(); await writer.upsertConversation(conversation); await writer.putImageAsset(asset);
 const versions = new current.WritingVersionService(writer);
 const version = await versions.create({ requestId: 'native-request', messageId: 'native-message', conversationId: conversation.id,
  turnIndex: 0, text: '第一行：“精确保真。”\nC:\\notes\\draft.md 🙂\n保留  双空格', images, scene,
  styleRevisionIds: ['style-one'], backgroundSourceRefs: [{ path: 'notes/synthetic.md' }] });
 const turns = [{ conversationId: conversation.id, turnIndex: 0, user: { role: 'user', content: 'Synthetic write', images },
  assistant: { role: 'assistant', content: version.text, writingVersionId: version.id, images } },
 { conversationId: conversation.id, turnIndex: 1, user: { role: 'user', content: 'Synthetic edit' },
  assistant: { role: 'assistant', content: 'Partial synthetic work', images,
   writingRecovery: { requestId: 'recovery-request', messageId: 'recovery-message', rawText: '{"kind":"pa.writing","body":"partial',
    reason: 'incomplete', parentVersionId: version.id, scene, backgroundSourceRefs: [{ path: 'notes/synthetic.md' }] } } }];
 for (const turn of turns) await writer.appendTurn(turn);
 await writer.putSaveReceipt({ id: 'save-one', operationId: 'save-one', writingVersionId: version.id, textHash: version.textHash,
  targetNotePath: 'Saved/synthetic.md', origin: 'ai_generated', createdAt: 1, attachments: [],
  initialNoteHash: 'b'.repeat(64), noteContentHash: 'c'.repeat(64), noteState: 'pending', state: 'prepared' });
 const before = await snapshot(writer); fs.writeFileSync(__dirname + '/generated-data.json', JSON.stringify(before, null, 2));
 versions.dispose(); await writer.dispose();
 const older = new old.IndexedDbChatHistoryStore('b135-compat-real-version', factory);
 let failure;
 try { await older.initialize(); } catch (error) { failure = { name: error.name, message: error.message }; }
 assert.equal(failure?.name, 'VersionError');
 report.results.push({ case: 'actual_292_opens_current_v2', outcome: 'INCOMPATIBLE', error: failure });
 report.results.push({ case: 'actual_292_reader_APIs', methods: Object.fromEntries(['getWritingVersion', 'listWritingVersions',
  'getImageAsset', 'getSaveReceipt', 'listSaveReceipts'].map(name => [name, typeof older[name]])) });
 await older.dispose();
 const reopened = new current.IndexedDbChatHistoryStore('b135-compat-real-version', factory); await reopened.initialize();
 assert.deepEqual(await snapshot(reopened), before);
 report.results.push({ case: 'current_reopens_after_failed_292_open', outcome: 'PASS', preserved: ['turns', 'writing versions', 'recovery scene', 'images', 'save receipts'] });
 await reopened.dispose();
 // Diagnose the old message projector separately; this does not bypass or claim IDB downgrade support.
 const memory = new old.MemoryChatHistoryStore(); await memory.initialize();
 for (const turn of turns) await memory.appendTurn(turn);
 const projected = await memory.getTurns(conversation.id);
 assert.equal(projected[0].assistant.content, version.text);
 assert.equal(projected[0].assistant.writingVersionId, undefined);
 assert.equal(projected[0].assistant.images, undefined);
 assert.equal(projected[1].assistant.writingRecovery, undefined);
 report.results.push({ case: 'actual_292_memory_message_projection_diagnostic', outcome: 'TEXT_ONLY',
  dropped: ['writingVersionId', 'images', 'writingRecovery including scene'], projected });
 // Supported upgrade direction: real old writer -> current reader, same versioned database.
 const oldFirst = new old.IndexedDbChatHistoryStore('b135-compat-upgrade', factory); await oldFirst.initialize();
 await oldFirst.upsertConversation(conversation);
 const legacyTurn = { conversationId: conversation.id, turnIndex: 0, user: { role: 'user', content: 'Old question' },
  assistant: { role: 'assistant', content: 'Old text answer' } };
 await oldFirst.appendTurn(legacyTurn); await oldFirst.dispose();
 const upgrade = new current.IndexedDbChatHistoryStore('b135-compat-upgrade', factory); await upgrade.initialize();
 assert.deepEqual(await upgrade.getTurns(conversation.id), [legacyTurn]);
 assert.deepEqual(await upgrade.listWritingVersions(conversation.id), []);
 report.results.push({ case: 'actual_292_v1_writer_to_current_v2_reader', outcome: 'PASS' });
 await upgrade.dispose();
 report.limitations = ['fake-indexeddb 6.2.4 implements real version admission; no Obsidian UI or real browser tested.',
  'No old writing/image/SaveReceipt reader exists in tag 2.9.2; no such API was invented.',
  'No persistent vault or current repository files modified; all data synthetic and isolated.'];
 fs.writeFileSync(__dirname + '/report.json', JSON.stringify(report, null, 2));
 console.log(JSON.stringify(report, null, 2));
}
main().catch(error => { console.error(error); process.exitCode = 1; });

