for (const [entry, out] of [['current-entry.ts', 'current.cjs'], ['old/src/chat/chat-history-store.ts', 'old.cjs']]) {
  esbuild.buildSync({ entryPoints: [__dirname + '/' + entry], outfile: __dirname + '/' + out,
    bundle: true, platform: 'node', format: 'cjs', target: 'node22',
    nodePaths: ['/mnt/code/personal-assistant/node_modules'], external: ['obsidian'] });
}
